<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useSessionStore } from '../stores/session'
import AppIcon from '../components/AppIcon.vue'
import FlowPreviewEditor from '../components/automation/FlowPreviewEditor.vue'
import ScenePreviewEditor from '../components/automation/ScenePreviewEditor.vue'
import { products, kindNames, statusNames, newFlow, newScene, sampleMessage, evaluateFlow, useAutomationPreview, type Flow, type Scene, type Connection, type Channel, type NoticeTemplate, type Run } from '../automation/preview'
import '../styles/automation.css'

const route = useRoute(), session = useSessionStore(), store = useAutomationPreview()
const sections = [
  { key: 'flows', title: '数据流转', icon: 'workflow', eyebrow: 'DATA FLOWS', description: '让设备数据，抵达需要它的地方。' },
  { key: 'scenes', title: '场景自动化', icon: 'layers', eyebrow: 'SCENE AUTOMATION', description: '连接条件与动作，让设备开始协同工作。' },
  { key: 'connections', title: '连接管理', icon: 'connection', eyebrow: 'CONNECTIONS', description: '管理业务系统连接，在不同规则之间复用。' },
  { key: 'notifications', title: '通知管理', icon: 'bell', eyebrow: 'NOTIFICATIONS', description: '维护通知渠道和模板，让重要消息有所归处。' },
  { key: 'runs', title: '运行记录', icon: 'clock', eyebrow: 'EXECUTION HISTORY', description: '从规则命中到动作结果，追踪每一次运行。' },
] as const
const section = computed(() => sections.find(s => s.key === route.meta.automationSection) || sections[0])
watch(() => session.account?.username, owner => store.bindOwner(owner || 'preview'), { immediate: true })
const query = ref(''), status = ref('all'), noticeTab = ref('channels')
const editingFlow = ref<Flow | null>(null), editingScene = ref<Scene | null>(null)
watch(() => !!editingFlow.value || !!editingScene.value, () => window.scrollTo({ top: 0 }), { flush: 'post' })
const connectionDialog = ref(false), channelDialog = ref(false), templateDialog = ref(false)
const connection = ref<Connection>({ id: '', name: '', kind: 'HTTPS', address: '', target: '', enabled: true, tested: false })
const channel = ref<Channel>({ id: '', name: '', kind: '邮件', recipient: '', enabled: true })
const template = ref<NoticeTemplate>({ id: '', name: '', channelId: '', content: '' })
const dialogError = ref(''), connectionTested = ref(false), record = ref<Run | null>(null)
const testScene = ref<Scene | null>(null), temperature = ref(32), testTime = ref('10:00'), sceneTestResult = ref('')
const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value))
function matches(name: string, value: string) { return name.toLowerCase().includes(query.value.trim().toLowerCase()) && (status.value === 'all' || status.value === value) }
const flows = computed(() => store.flows.filter(f => matches(f.name, f.status)))
const scenes = computed(() => store.scenes.filter(s => matches(s.name, s.status)))
const connections = computed(() => store.connections.filter(c => matches(c.name, c.enabled ? 'running' : 'paused')))
const runs = computed(() => store.runs.filter(r => matches(`${r.name} ${r.id}`, r.status)))
const channels = computed(() => store.channels.filter(c => matches(c.name, c.enabled ? 'running' : 'paused')))
const templates = computed(() => store.templates.filter(t => t.name.includes(query.value.trim())))
const runningFlows = computed(() => store.flows.filter(f => f.status === 'running').length)
const failedRuns = computed(() => store.runs.filter(r => r.status === 'failed').length)
const productName = (id: string) => products.find(p => p.id === id)?.name || id
const connectionName = (id: string) => store.connections.find(c => c.id === id)?.name || '连接已移除'
const channelName = (id: string) => store.channels.find(c => c.id === id)?.name || '渠道已移除'
const runNames = { success: '模拟成功', failed: '模拟失败', filtered: '未命中' }
function date(value: string) { return new Date(value).toLocaleString('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', timeZone: 'Asia/Shanghai' }) }
function persist<T extends { id: string }>(items: T[], item: T) { if (!item.id) item.id = crypto.randomUUID(); const i = items.findIndex(v => v.id === item.id); if (i < 0) items.unshift(item); else items.splice(i, 1, item) }
function saveFlow(flow: Flow) { persist(store.flows, flow); editingFlow.value = null; ElMessage.success(flow.status === 'running' ? '演示规则已发布，可进行本地试运行' : '演示草稿已保存') }
function saveScene(scene: Scene) { persist(store.scenes, scene); editingScene.value = null; ElMessage.success('演示场景已保存') }
async function removeRule(type: 'flow' | 'scene', id: string) {
  try { await ElMessageBox.confirm('删除后将从本次演示中移除，已有运行记录继续保留。', '删除演示规则', { confirmButtonText: '删除', cancelButtonText: '取消', type: 'warning' }) }
  catch { return }
  if (type === 'flow') store.flows = store.flows.filter(f => f.id !== id)
  else store.scenes = store.scenes.filter(s => s.id !== id)
}
function toggleRule(rule: Flow | Scene) {
  if (rule.status === 'draft') return
  rule.status = rule.status === 'running' ? 'paused' : 'running'
  ElMessage.success(rule.status === 'running' ? '演示规则已启用' : '演示规则已停用')
}
function runFlow(flow: Flow) {
  const disabled = flow.connectionIds.some(id => !store.connections.some(c => c.id === id && c.enabled))
  const input = sampleMessage(flow.product, flow.kind, flow.device)
  try {
    const result = evaluateFlow(flow, input)
    store.record({ name: flow.name, type: '数据流转', status: !result.matched ? 'filtered' : disabled ? 'failed' : 'success', detail: !result.matched ? result.reason : disabled ? '模拟失败：目标连接已停用' : `本地模拟完成，目标：${flow.connectionIds.map(connectionName).join('、')}；未发送网络请求`, input, output: result.output })
  } catch (e) { store.record({ name: flow.name, type: '数据流转', status: 'failed', detail: e instanceof Error ? e.message : '模拟计算失败', input, output: null }) }
  record.value = store.runs[0] || null
}
function openSceneTest(scene: Scene) { testScene.value = clone(scene); temperature.value = 32; testTime.value = '10:00'; sceneTestResult.value = '' }
function simulateScene() {
  const scene = testScene.value
  if (!scene) return
  if (!scene.manual && (!Number.isFinite(temperature.value) || !/^\d{2}:\d{2}$/.test(testTime.value))) { sceneTestResult.value = '请填写有效的温度与时间'; return }
  const inTime = scene.start <= scene.end ? testTime.value >= scene.start && testTime.value <= scene.end : testTime.value >= scene.start || testTime.value <= scene.end
  const matched = scene.manual || temperature.value > scene.threshold && inTime
  const invalidAction = scene.actions.some(a => a.kind === 'connection' ? !store.connections.some(c => c.id === a.target && c.enabled) : a.kind === 'notification' ? !store.templates.some(t => t.id === a.target && store.channels.some(c => c.id === t.channelId && c.enabled)) : false)
  sceneTestResult.value = !matched ? '未命中：温度条件或生效时间不满足。' : invalidAction ? '模拟失败：动作引用的连接或通知渠道已停用。' : `模拟命中：生成 ${scene.actions.length} 个顺序动作。未控制设备、发送通知或实际等待延时。`
  store.record({ name: scene.name, type: '场景自动化', status: !matched ? 'filtered' : invalidAction ? 'failed' : 'success', detail: sceneTestResult.value, input: { device: scene.device, temperature: temperature.value, time: testTime.value, manual: scene.manual }, output: matched ? scene.actions : null })
}
function openConnection(item?: Connection) { connection.value = item ? clone(item) : { id: '', name: '', kind: 'HTTPS', address: '', target: '', enabled: true, tested: false }; connectionDialog.value = true; dialogError.value = ''; connectionTested.value = false }
function checkConnection(): string {
  if (!connection.value.name.trim()) return '请填写连接名称'
  if (connection.value.kind === 'HTTPS') { try { const url = new URL(connection.value.address); if (url.protocol !== 'https:' || url.username || url.password) return '请输入不包含账号密码的 HTTPS 地址' } catch { return '请输入有效的 HTTPS 地址' } }
  else if (!/^[a-zA-Z0-9.-]+:\d{2,5}$/.test(connection.value.address) || !connection.value.target.trim()) return '请填写 host:port 格式的地址和目标 Topic'
  return ''
}
watch(connection, () => { connectionTested.value = false }, { deep: true })
function testConnection() { dialogError.value = checkConnection(); if (!dialogError.value) connectionTested.value = true }
function saveConnection() { dialogError.value = checkConnection(); if (dialogError.value) return; persist(store.connections, { ...connection.value, tested: connectionTested.value }); connectionDialog.value = false; ElMessage.success('示例连接已保存') }
function openChannel(item?: Channel) { channel.value = item ? clone(item) : { id: '', name: '', kind: '邮件', recipient: '', enabled: true }; channelDialog.value = true; dialogError.value = '' }
function saveChannel() {
  const c = channel.value
  if (!c.name.trim() || !c.recipient.trim()) { dialogError.value = '请填写渠道名称和接收对象'; return }
  if (c.kind === '邮件' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.recipient)) { dialogError.value = '请输入有效的邮箱地址'; return }
  persist(store.channels, clone(c)); channelDialog.value = false; ElMessage.success('示例通知渠道已保存')
}
function openTemplate(item?: NoticeTemplate) { template.value = item ? clone(item) : { id: '', name: '', channelId: store.channels[0]?.id || '', content: '设备 {{deviceName}} 当前温度为 {{temperature}}℃，请及时关注。' }; templateDialog.value = true; dialogError.value = '' }
function saveTemplate() { if (!template.value.name.trim() || !template.value.content.trim() || !store.channels.some(c => c.id === template.value.channelId)) { dialogError.value = '请填写模板名称、内容并选择渠道'; return }; persist(store.templates, clone(template.value)); templateDialog.value = false; ElMessage.success('示例模板已保存') }
function renderTemplate(content: string) { return content.replaceAll('{{deviceName}}', '婴儿房 · 温湿度传感器').replaceAll('{{temperature}}', '32') }
function replay(run: Run) { run.attempts++; run.status = 'success'; run.detail = '人工重试演示完成，未向真实目标发送数据'; ElMessage.success('本地模拟重试完成') }
</script>

<template>
  <div class="automation-workspace">
    <div class="preview-notice"><span class="preview-label">交互预览</span><span>以下为示例数据，修改仅保留在当前浏览会话；刷新后重置。所有发布、投递与设备动作均为本地模拟。</span></div>
    <nav class="automation-tabs" aria-label="规则与集成"><RouterLink v-for="s in sections" :key="s.key" :to="`/automation/${s.key}`" :class="{ active: section.key === s.key }" :aria-current="section.key === s.key ? 'page' : undefined"><AppIcon :name="s.icon" :size="17"/>{{ s.title }}<span v-if="s.key === 'runs' && failedRuns" class="tab-badge">{{ failedRuns }}</span></RouterLink></nav>
    <FlowPreviewEditor v-if="editingFlow" :flow="editingFlow" @close="editingFlow = null" @save="saveFlow"/>
    <ScenePreviewEditor v-else-if="editingScene" :scene="editingScene" @close="editingScene = null" @save="saveScene"/>
    <template v-else>
      <header class="page-heading automation-heading"><div><p class="eyebrow">{{ section.eyebrow }}</p><h1>{{ section.title }}</h1><p>{{ section.description }}</p></div><el-button v-if="section.key === 'flows'" type="primary" @click="editingFlow = newFlow()">＋ 新建流转规则</el-button><el-button v-else-if="section.key === 'scenes'" type="primary" @click="editingScene = newScene()">＋ 新建场景</el-button><el-button v-else-if="section.key === 'connections'" type="primary" @click="openConnection()">＋ 新建连接</el-button><el-button v-else-if="section.key === 'notifications'" type="primary" @click="noticeTab === 'channels' ? openChannel() : openTemplate()">＋ {{ noticeTab === 'channels' ? '新建通知渠道' : '新建通知模板' }}</el-button></header>
      <template v-if="section.key === 'flows'">
        <section class="flow-introduction panel"><div class="flow-intro-copy"><span class="intro-kicker">一条规则，连接设备与业务</span><h2>从消息，到业务价值。</h2><p>原样转发，或按需筛选与转换。<br/>把数据处理留给平台，把业务创造留给你。</p><button class="text-action" @click="editingFlow = newFlow()">创建第一条数据链路 <span>↗</span></button></div><div class="pipeline-illustration" aria-label="消息源、数据处理、转发目标"><div class="pipeline-node"><span class="node-icon blue"><AppIcon name="device" :size="24"/></span><strong>消息源</strong><small>产品与设备</small></div><div class="pipeline-wire"><i></i><span>→</span></div><div class="pipeline-node"><span class="node-icon purple"><AppIcon name="workflow" :size="24"/></span><strong>数据处理</strong><small>筛选 · 转换 · 可选</small></div><div class="pipeline-wire"><i></i><span>→</span></div><div class="pipeline-node"><span class="node-icon green"><AppIcon name="layers" :size="24"/></span><strong>转发目标</strong><small>Server / MQ</small></div></div></section>
        <div class="automation-metrics"><div><span>流转规则</span><strong>{{ store.flows.length }}<small>条</small></strong></div><div><span><i class="tiny-dot"></i>运行中</span><strong>{{ runningFlows }}<small>条</small></strong></div><div><span>可用连接</span><strong>{{ store.connections.filter(c => c.enabled).length }}<small>个</small></strong></div><div><span>待处理失败</span><strong :class="{ 'warning-number': failedRuns }">{{ failedRuns }}<small>条示例</small></strong></div></div>
      </template>
      <div v-if="section.key === 'notifications'" class="notice-tabs"><button :class="{ active: noticeTab === 'channels' }" @click="noticeTab = 'channels'; query = ''; status = 'all'">通知渠道 <span>{{ store.channels.length }}</span></button><button :class="{ active: noticeTab === 'templates' }" @click="noticeTab = 'templates'; query = ''; status = 'all'">消息模板 <span>{{ store.templates.length }}</span></button></div>
      <section class="panel rules-panel"><div class="rules-toolbar"><div class="toolbar-title"><h2>{{ section.key === 'flows' ? '流转规则' : section.key === 'scenes' ? '全部场景' : section.key === 'connections' ? '外部连接' : section.key === 'runs' ? '最近运行' : noticeTab === 'channels' ? '通知渠道' : '消息模板' }}</h2><span class="sample-caption">示例工作空间</span></div><div class="toolbar-filters"><el-input v-model="query" clearable :placeholder="section.key === 'runs' ? '搜索名称或记录 ID' : '搜索名称'" aria-label="搜索名称"><template #prefix><AppIcon name="search" :size="15"/></template></el-input><el-select v-if="section.key !== 'notifications' || noticeTab === 'channels'" v-model="status" aria-label="状态筛选"><el-option value="all" label="全部状态"/><template v-if="section.key === 'runs'"><el-option v-for="(label, key) in runNames" :key="key" :value="key" :label="label"/></template><template v-else><el-option value="running" :label="section.key === 'connections' || section.key === 'notifications' ? '已启用' : '运行中'"/><el-option value="paused" label="已停用"/><el-option v-if="section.key === 'flows' || section.key === 'scenes'" value="draft" label="草稿"/></template></el-select></div></div>
        <el-table v-if="section.key === 'flows'" :data="flows" empty-text="没有匹配的流转规则，试试调整筛选或新建规则。" class="automation-table"><el-table-column label="规则名称" min-width="240"><template #default="{ row }"><button class="rule-name" @click="editingFlow = clone(row)"><span class="row-icon"><AppIcon name="workflow" :size="17"/></span>{{ row.name }}</button><p class="row-description">{{ row.description || '暂无说明' }}</p></template></el-table-column><el-table-column label="消息源" min-width="160"><template #default="{ row }"><span>{{ productName(row.product) }}</span><p class="row-description">{{ kindNames[row.kind as keyof typeof kindNames] }} · {{ row.device ? '指定设备' : '全部设备' }}</p></template></el-table-column><el-table-column label="处理方式" width="118"><template #default="{ row }"><span class="processing-tag" :class="{ transformed: row.processing }">{{ row.processing ? '筛选与转换' : '原样转发' }}</span></template></el-table-column><el-table-column label="转发目标" min-width="155"><template #default="{ row }"><p v-for="id in row.connectionIds" :key="id" class="target-name">{{ connectionName(id) }}</p></template></el-table-column><el-table-column label="状态" width="105"><template #default="{ row }"><span class="status-pill" :class="row.status"><i></i>{{ statusNames[row.status as keyof typeof statusNames] }}</span><p class="row-description">{{ row.version ? `v${row.version}` : '未发布' }}</p></template></el-table-column><el-table-column label="操作" width="198" fixed="right"><template #default="{ row }"><div class="table-actions"><el-button link type="primary" @click="editingFlow = clone(row)">编辑</el-button><el-button link :disabled="row.status !== 'running'" @click="runFlow(row)">试运行</el-button><el-dropdown trigger="click"><el-button text :aria-label="`${row.name}更多操作`">···</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item :disabled="row.status === 'draft'" @click="toggleRule(row)">{{ row.status === 'running' ? '停用' : '启用' }}</el-dropdown-item><el-dropdown-item @click="editingFlow = { ...clone(row), id: '', name: `${row.name} · 副本`, status: 'draft', version: 0 }">复制规则</el-dropdown-item><el-dropdown-item divided @click="removeRule('flow', row.id)">删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></template></el-table-column></el-table>
        <el-table v-else-if="section.key === 'scenes'" :data="scenes" empty-text="暂无匹配场景，可新建自动化或一键执行。"><el-table-column label="场景名称" min-width="230"><template #default="{ row }"><button class="rule-name" @click="editingScene = clone(row)"><span class="row-icon purple"><AppIcon name="layers" :size="17"/></span>{{ row.name }}</button><p class="row-description">{{ row.description }}</p></template></el-table-column><el-table-column label="触发方式" min-width="165"><template #default="{ row }"><span>{{ row.manual ? '一键执行' : '设备温度上报' }}</span><p class="row-description">{{ row.manual ? '手动触发' : `温度 > ${row.threshold}℃ · 冷却 ${row.cooldown} 分钟` }}</p></template></el-table-column><el-table-column label="执行动作" min-width="130"><template #default="{ row }">{{ row.actions.length }} 个顺序动作</template></el-table-column><el-table-column label="状态" width="110"><template #default="{ row }"><span class="status-pill" :class="row.status"><i></i>{{ statusNames[row.status as keyof typeof statusNames] }}</span></template></el-table-column><el-table-column label="操作" width="230"><template #default="{ row }"><div class="table-actions"><el-button link type="primary" @click="editingScene = clone(row)">编辑</el-button><el-button link :disabled="row.status !== 'running'" @click="openSceneTest(row)">{{ row.manual ? '模拟执行' : '试运行' }}</el-button><el-dropdown trigger="click"><el-button text aria-label="场景更多操作">···</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item :disabled="row.status === 'draft'" @click="toggleRule(row)">{{ row.status === 'running' ? '停用' : '启用' }}</el-dropdown-item><el-dropdown-item @click="editingScene = { ...clone(row), id: '', name: `${row.name} · 副本`, status: 'draft', version: 0 }">复制场景</el-dropdown-item><el-dropdown-item divided @click="removeRule('scene', row.id)">删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></template></el-table-column></el-table>
        <div v-else-if="section.key === 'connections'" class="connection-grid"><article v-for="c in connections" :key="c.id" class="connection-card"><div class="connection-card-top"><span class="connection-monogram large" :class="c.kind.toLowerCase()">{{ c.kind === 'HTTPS' ? 'H' : c.kind === 'Kafka' ? 'K' : 'R' }}</span><span class="status-pill" :class="c.enabled ? 'running' : 'paused'"><i></i>{{ c.enabled ? '已启用' : '已停用' }}</span></div><h3>{{ c.name }}</h3><span class="connection-kind">{{ c.kind }}</span><p class="connection-address">{{ c.address }}</p><p class="connection-topic">{{ c.target ? `Topic · ${c.target}` : 'HTTPS 消息接收端点' }}</p><div class="connection-card-bottom"><span>{{ store.flows.filter(f => f.connectionIds.includes(c.id)).length }} 条流转规则引用</span><el-button link type="primary" @click="openConnection(c)">配置连接 →</el-button></div></article><div v-if="!connections.length" class="workspace-empty">没有匹配的连接，请调整筛选或新建连接。</div></div>
        <el-table v-else-if="section.key === 'runs'" :data="runs" empty-text="暂无运行记录，可先试运行一条规则。"><el-table-column label="规则 / 场景" min-width="230"><template #default="{ row }"><button class="rule-name" @click="record = row">{{ row.name }}</button><p class="row-description mono">{{ row.id }}</p></template></el-table-column><el-table-column prop="type" label="类型" width="125"/><el-table-column label="结果" width="120"><template #default="{ row }"><span class="status-pill" :class="row.status">{{ runNames[row.status as keyof typeof runNames] }}</span></template></el-table-column><el-table-column label="运行时间（上海）" min-width="165"><template #default="{ row }">{{ date(row.time) }}</template></el-table-column><el-table-column label="操作" width="160"><template #default="{ row }"><el-button link type="primary" @click="record = row">详情</el-button><el-button v-if="row.status === 'failed'" link @click="replay(row)">模拟重试</el-button></template></el-table-column></el-table>
        <el-table v-else-if="noticeTab === 'channels'" :data="channels" empty-text="暂无匹配通知渠道。"><el-table-column label="渠道名称" min-width="200"><template #default="{ row }"><button class="rule-name" @click="openChannel(row)"><span class="row-icon"><AppIcon name="bell" :size="17"/></span>{{ row.name }}</button></template></el-table-column><el-table-column prop="kind" label="渠道类型" width="120"/><el-table-column prop="recipient" label="接收对象" min-width="200"/><el-table-column label="状态" width="120"><template #default="{ row }"><span class="status-pill" :class="row.enabled ? 'running' : 'paused'">{{ row.enabled ? '已启用' : '已停用' }}</span></template></el-table-column><el-table-column label="操作" width="110"><template #default="{ row }"><el-button link type="primary" @click="openChannel(row)">配置</el-button></template></el-table-column></el-table>
        <el-table v-else :data="templates" empty-text="暂无匹配通知模板。"><el-table-column prop="name" label="模板名称" min-width="180"/><el-table-column label="通知渠道" min-width="160"><template #default="{ row }">{{ channelName(row.channelId) }}</template></el-table-column><el-table-column prop="content" label="内容" min-width="300" show-overflow-tooltip/><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link type="primary" @click="openTemplate(row)">编辑</el-button></template></el-table-column></el-table>
        <div class="table-footer"><span>{{ section.key === 'runs' ? '最多保留本次会话的 100 条模拟运行记录' : '配置在本次浏览会话内共享，可切换页面继续体验' }}</span><span>演示数据</span></div>
      </section>
      <div v-if="section.key === 'scenes'" class="bottom-hint"><AppIcon name="shield" :size="17"/><p>自动化用于设备与业务动作编排；需要把消息交给自己的 Server，请使用 <RouterLink to="/automation/flows">数据流转 →</RouterLink></p></div>
      <div v-if="section.key === 'notifications'" class="bottom-hint"><AppIcon name="bell" :size="17"/><p>通知渠道与模板独立维护。可被自动化引用，后续也可用于升级任务、生产交付等业务。</p></div>
    </template>

    <el-dialog v-model="connectionDialog" title="配置外部连接" width="560px" destroy-on-close><p class="dialog-intro">维护目标地址，供数据流转和场景动作复用。演示连接无需填写真实凭证。</p><el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false"/><el-form label-position="top" class="dialog-form"><el-form-item label="连接名称"><el-input v-model="connection.name" aria-label="连接名称" maxlength="60"/></el-form-item><el-form-item label="连接类型"><el-radio-group v-model="connection.kind"><el-radio-button value="HTTPS">HTTPS</el-radio-button><el-radio-button value="Kafka">Kafka</el-radio-button><el-radio-button value="RocketMQ">RocketMQ</el-radio-button></el-radio-group></el-form-item><el-form-item :label="connection.kind === 'HTTPS' ? '接收地址' : 'Broker 地址（host:port）'"><el-input v-model="connection.address" aria-label="连接地址" :placeholder="connection.kind === 'HTTPS' ? 'https://api.example.com/iot/events' : 'broker.example.com:9093'" maxlength="500"/></el-form-item><el-form-item v-if="connection.kind !== 'HTTPS'" label="目标 Topic"><el-input v-model="connection.target" aria-label="目标 Topic" maxlength="100"/></el-form-item><el-form-item label="启用状态"><el-switch v-model="connection.enabled" aria-label="启用连接"/></el-form-item></el-form><el-alert v-if="connectionTested" title="示例配置校验通过；未连接真实服务，也未验证网络或认证。" type="success" :closable="false"/><template #footer><el-button @click="testConnection">校验示例配置</el-button><el-button @click="connectionDialog = false">取消</el-button><el-button type="primary" @click="saveConnection">保存示例连接</el-button></template></el-dialog>
    <el-dialog v-model="channelDialog" title="配置通知渠道" width="520px" destroy-on-close><p class="dialog-intro">演示接收对象与渠道配置，不发送真实通知。</p><el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false"/><el-form label-position="top" class="dialog-form"><el-form-item label="渠道名称"><el-input v-model="channel.name" aria-label="渠道名称" maxlength="60"/></el-form-item><el-form-item label="渠道类型"><el-select v-model="channel.kind"><el-option v-for="k in ['邮件', '短信', 'App 推送']" :key="k" :value="k" :label="k"/></el-select></el-form-item><el-form-item :label="channel.kind === '邮件' ? '接收邮箱' : channel.kind === '短信' ? '接收手机号（演示）' : '应用接收标识（演示）'"><el-input v-model="channel.recipient" aria-label="通知接收对象" maxlength="150"/></el-form-item><el-form-item label="启用状态"><el-switch v-model="channel.enabled" aria-label="启用渠道"/></el-form-item></el-form><template #footer><el-button @click="channelDialog = false">取消</el-button><el-button type="primary" @click="saveChannel">保存示例渠道</el-button></template></el-dialog>
    <el-dialog v-model="templateDialog" title="编辑通知模板" width="580px" destroy-on-close><el-alert v-if="dialogError" :title="dialogError" type="error" :closable="false"/><el-form label-position="top" class="dialog-form"><el-form-item label="模板名称"><el-input v-model="template.name" aria-label="模板名称" maxlength="60"/></el-form-item><el-form-item label="通知渠道"><el-select v-model="template.channelId"><el-option v-for="c in store.channels" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="消息内容"><el-input v-model="template.content" type="textarea" :rows="4" aria-label="模板内容" maxlength="1000"/></el-form-item></el-form><p class="field-help">支持演示变量：<code v-pre>{{deviceName}}</code>、<code v-pre>{{temperature}}</code></p><div class="template-preview"><span>内容预览</span><p>{{ renderTemplate(template.content) }}</p></div><template #footer><el-button @click="templateDialog = false">取消</el-button><el-button type="primary" @click="saveTemplate">保存示例模板</el-button></template></el-dialog>
    <el-dialog :model-value="!!testScene" :title="`试运行 · ${testScene?.name || ''}`" width="560px" @update:model-value="(value: boolean) => { if (!value) testScene = null }"><template v-if="testScene"><p class="dialog-intro">单次条件与动作预览，不模拟连续事件的冷却状态，也不执行设备、通知或延时。</p><el-form v-if="!testScene.manual" label-position="top" class="dialog-form"><el-form-item label="模拟上报温度（℃）"><el-input-number v-model="temperature" aria-label="模拟温度"/></el-form-item><el-form-item label="模拟本地时间"><el-input v-model="testTime" type="time" aria-label="模拟时间"/></el-form-item></el-form><div v-if="sceneTestResult" class="template-preview" aria-live="polite"><p>{{ sceneTestResult }}</p></div></template><template #footer><el-button @click="testScene = null">关闭</el-button><el-button type="primary" @click="simulateScene">运行本地模拟</el-button></template></el-dialog>
    <el-drawer :model-value="!!record" title="运行详情" size="min(600px, 100vw)" @close="record = null"><template v-if="record"><div class="run-detail-title"><span class="status-pill" :class="record.status">{{ runNames[record.status] }}</span><h2>{{ record.name }}</h2><p>{{ record.id }} · {{ date(record.time) }}</p></div><div class="run-steps"><div><span class="step-number">01</span><p><strong>输入消息</strong><small>本地生成的示例输入</small></p></div><pre class="code-block">{{ JSON.stringify(record.input, null, 2) }}</pre><div><span class="step-number purple">02</span><p><strong>计算与动作结果</strong><small>{{ record.detail }}</small></p></div><pre class="code-block">{{ JSON.stringify(record.output, null, 2) }}</pre></div><p class="field-help">尝试次数 {{ record.attempts }} · 演示记录，不代表真实设备或外部系统已执行。</p><el-button v-if="record.status === 'failed'" type="primary" @click="replay(record)">模拟重试</el-button></template></el-drawer>
  </div>
</template>
